 "content": "def transform(grid):
    """Fill background gaps between repeated same-row markers with color 2."""
    from collections import Counter

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != background]
        if len(markers) >= 2:
            for c in range(min(markers), max(markers) + 1):
                if row[c] == background:
                    out[r][c] = 2
    return out
